def get_credential_cryptography_catalog() -> List[CredentialCryptographyRecord]:
    """Return complete credential_cryptography registry."""
    return REGISTRY_CREDENTIAL_CRYPTOGRAPHY


def query_credential_cryptography_by_difficulty(difficulty_level: str) -> List[CredentialCryptographyRecord]:
    """Filter credential_cryptography elements matching difficulty."""
    return [item for item in REGISTRY_CREDENTIAL_CRYPTOGRAPHY if item.difficulty == difficulty_level]


def calculate_credential_cryptography_total_weight() -> float:
    """Compute cumulative weighting of curriculum units."""
    return sum(item.weight for item in REGISTRY_CREDENTIAL_CRYPTOGRAPHY)

